#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L, C;
    cin >> L >> C;

    int P;
    cin >> P;

    vector<vector<bool>> black(L, vector<bool>(C, false));
    for (int i = 0; i < P; i++) {
        int x, y;
        cin >> x >> y;
        --x; --y;
        black[x][y] = true;
    }

    vector<int> eligible(L, 0);
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    for (int r = 0; r < L; r++) {
        for (int c = 0; c < C; c++) {
            if (black[r][c]) continue;

            bool ok = false;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < L && nc >= 0 && nc < C && black[nr][nc]) {
                    ok = true;
                    break;
                }
            }

            if (ok) eligible[r] |= (1 << c);
        }
    }

    const int INF = -1e9;
    vector<int> dp(1 << C, INF);
    dp[0] = 0;

    for (int r = 0; r < L; r++) {
        vector<int> ndp(1 << C, INF);

        for (int mask = 0; mask < (1 << C); mask++) {
            if ((mask & ~eligible[r]) != 0) continue;
            if ((mask & (mask << 1)) != 0) continue;

            int cnt = __builtin_popcount(mask);

            for (int prev = 0; prev < (1 << C); prev++) {
                if (dp[prev] == INF) continue;
                if ((mask & prev) != 0) continue;

                ndp[mask] = max(ndp[mask], dp[prev] + cnt);
            }
        }

        dp = ndp;
    }

    int ans = 0;
    for (int mask = 0; mask < (1 << C); mask++) {
        ans = max(ans, dp[mask]);
    }

    cout << ans << '\n';

    return 0;
}
